package dev.kelmagic.client;
import dev.kelmagic.*;import dev.kelmagic.content.*;import dev.kelmagic.server.*;import dev.kelmagic.entity.*;import dev.kelmagic.research.*;
import net.minecraft.client.*;import net.minecraft.client.gui.screens.TitleScreen;import net.minecraft.core.*;import net.minecraft.core.registries.*;import net.minecraft.nbt.*;import net.minecraft.server.level.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.entity.*;import net.minecraft.world.item.*;import net.minecraft.world.phys.*;import java.util.*;import java.nio.file.*;
@net.neoforged.fml.common.EventBusSubscriber(modid="kelmagic",value=net.neoforged.api.distmarker.Dist.CLIENT)
public final class QaR12Roots {
 static final Path OUT=Path.of(System.getProperty("kelmagic.qaOutput","qa-r12"));static boolean opened,requested,configured;static volatile boolean ready,smallDone,benchDone;static int wait,frame,checks,monitor,stage=-1;static long benchStart;static volatile Throwable failure;static final BlockPos BED=new BlockPos(200,-60,0),TREE=new BlockPos(180,-60,0),FIELD=new BlockPos(205,-61,30),GROVE=new BlockPos(325,-60,0),BENCH=new BlockPos(800,-60,800);
 static void ok(boolean b,String m){checks++;if(!b)throw new AssertionError("R12 "+m);System.out.println("R12_PASS "+m);}
 static void server(java.util.function.Consumer<ServerPlayer> f){var m=Minecraft.getInstance();m.getSingleplayerServer().execute(()->{try{f.accept(m.getSingleplayerServer().getPlayerList().getPlayers().getFirst());}catch(Throwable e){e.printStackTrace();failure=e;}});}
 static void put(ServerLevel l,BlockPos p,net.minecraft.world.level.block.state.BlockState s){l.setBlock(p,s,2);}
 static void clear(ServerLevel l,BlockPos p,int r,int h){for(var q:BlockPos.betweenClosed(p.offset(-r,0,-r),p.offset(r,h,r)))if(!l.getBlockState(q).isAir())put(l,q,Blocks.AIR.defaultBlockState());}
 static void camera(ServerPlayer p,Vec3 eye,Vec3 target){QaR10Dreams.camera(p,eye,target);}
 static void aim(ServerPlayer p,BlockPos at){var d=Vec3.atCenterOf(at).add(0,.45,0).subtract(p.getEyePosition());p.teleportTo(p.serverLevel(),p.getX(),p.getY(),p.getZ(),(float)Math.toDegrees(Math.atan2(-d.x,d.z)),(float)-Math.toDegrees(Math.atan2(d.y,Math.hypot(d.x,d.z))));}
 static CompoundTag jobTag(ServerPlayer p,BlockPos center,int radius,boolean cleaning){var n=new CompoundTag();n.putUUID("Owner",p.getUUID());n.putLong("Center",center.asLong());for(var k:List.of("West","East","North","South"))n.putInt(k,radius);n.putBoolean("CentreFirst",true);n.putInt("Phase",cleaning?1:0);var list=new ListTag();list.add(n);var save=new CompoundTag();save.put("Jobs",list);return save;}
 static void tests(ServerPlayer p){var l=p.serverLevel();p.gameMode.changeGameModeForPlayer(GameType.CREATIVE);p.getInventory().clearContent();p.teleportTo(l,200.5,-60,.5,0,0);l.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_WEATHER_CYCLE).set(false,p.server);l.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_DAYLIGHT).set(false,p.server);l.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_DOMOBSPAWNING).set(false,p.server);l.setDayTime(6000);l.setWeatherParameters(60000,0,false,false);for(int x=9;x<=22;x++)for(int z=-2;z<=4;z++)l.getChunk(x,z);clear(l,new BlockPos(230,-60,0),65,36);
  for(var id:List.of("grove_leaves","threshold_travel","living_fiber","rite_threshold_link"))ok(p.server.getAdvancements().get(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("kelmagic",id))==null,"removed advancement "+id);
  var table=new BlockPos(206,-60,-8);put(l,table,MagicStudy.TABLE.get().defaultBlockState());var entity=l.getBlockEntity(table);ok(entity instanceof dev.kelmagic.archive.ArchiveTableEntity,"real table entity");ok(MagicTransformation.transform(p,table),"nov transforms table lamp");ok(l.getBlockEntity(table)==entity,"table entity preserved");ok(MagicProgress.completed(p,"word_born_power"),"lamp transformation advancement awarded");
  var data=ThresholdLinks.get(p.server);data.ends.clear();p.teleportTo(l,200.5,-60,.5,0,-80);ok(!ThresholdLinks.open(p),"sky gaze does not create floating portal");var target=new BlockPos(201,-61,12);aim(p,target);ok(ThresholdLinks.target(p).getBlockPos().equals(target),"ray hits looked-at block");ok(ThresholdLinks.open(p),"portal opens on gaze target");var first=data.ends.values().stream().findFirst().orElseThrow();ok(first.at().distanceTo(Vec3.atBottomCenterOf(target.above()))<.001,"portal position is exactly above targeted block");target=new BlockPos(211,-61,12);aim(p,target);ok(ThresholdLinks.open(p),"second gaze portal");ok(MagicProgress.completed(p,"threshold_pair"),"pair advancement on actual link");
  for(var name:List.of("threshold_open","threshold_close","threshold_travel","threshold_hum"))ok(BuiltInRegistries.SOUND_EVENT.containsKey(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("kelmagic",name)),"unique registered sound "+name);
  var portal=(ThresholdPortal)l.getEntity(first.id());ThresholdLinks.close(portal,p);ok(data.ends.isEmpty(),"pair closes");
  for(var id:List.of("threshold_link","grove_awakening")){var r=dev.kelmagic.core.GrandSpells.ALL.stream().filter(v->v.id().equals(id)).findFirst().orElseThrow();p.gameMode.changeGameModeForPlayer(GameType.SURVIVAL);ok(!SpellEffects.execute(p,dev.kelmagic.core.SpellParser.plan(r.formula())),"survival still cannot cast "+id);p.gameMode.changeGameModeForPlayer(GameType.CREATIVE);}
  QaR10Dreams.bed(l,BED,Direction.NORTH);put(l,BED.below(),Blocks.GRASS_BLOCK.defaultBlockState());put(l,BED.north().below(),Blocks.GRASS_BLOCK.defaultBlockState());MagicDreams.TREE.get().place(new net.minecraft.world.level.levelgen.feature.FeaturePlaceContext<>(Optional.empty(),l,l.getChunkSource().getGenerator(),net.minecraft.util.RandomSource.create(42),TREE,net.minecraft.world.level.levelgen.feature.configurations.NoneFeatureConfiguration.INSTANCE));
  for(var q:BlockPos.betweenClosed(FIELD,FIELD.offset(47,0,31)))put(l,q,MagicDreams.GRASS.get().defaultBlockState());put(l,FIELD.offset(12,1,12),MagicResonance.MANA.get().defaultBlockState());put(l,FIELD.offset(35,1,12),MagicResonance.MANA.get().defaultBlockState());p.teleportTo(l,199,-60,3,0,0);aim(p,new BlockPos(204,-61,12));ok(ThresholdLinks.open(p),"presentation portal one");aim(p,new BlockPos(212,-61,12));ok(ThresholdLinks.open(p),"presentation portal two");
  clear(l,GROVE,22,35);for(int i=0;i<10;i++)put(l,new BlockPos(320+i,-60,0),MagicGrove.SAPLING.get().defaultBlockState());var root=GROVE.offset(-7,0,-6);for(int y=0;y<6;y++)put(l,root.above(y),Blocks.OAK_LOG.defaultBlockState());for(var q:BlockPos.betweenClosed(root.offset(-2,4,-2),root.offset(2,7,2)))if(l.getBlockState(q).isAir())put(l,q,Blocks.OAK_LEAVES.defaultBlockState());put(l,root.offset(4,10,1),Blocks.OAK_LOG.defaultBlockState());put(l,GROVE.offset(9,15,0),Blocks.OAK_LEAVES.defaultBlockState());put(l,GROVE.offset(9,0,0),Blocks.OAK_LOG.defaultBlockState());put(l,GROVE.offset(0,0,-3),Blocks.DANDELION.defaultBlockState());
  p.teleportTo(l,280.5,-60,.5,0,0);l.getDataStorage().set("kelmagic_grove_jobs",GroveAwakening.load(jobTag(p,p.blockPosition(),18,false),l.registryAccess()));ready=true;camera(p,new Vec3(202,-58,3),new Vec3(200.5,-59.5,0));
 }
 static void watch(ServerPlayer p){var l=p.serverLevel();var data=GroveAwakening.get(p.server);var saved=data.save(new CompoundTag(),l.registryAccess());var jobs=saved.getList("Jobs",10);
  if(!smallDone){if(!jobs.isEmpty()&&jobs.getCompound(0).getInt("Phase")==1&&monitor++==0){var n=jobs.getCompound(0);ok(BlockPos.of(n.getLong("Center")).equals(GROVE),"grove recentres at centroid of ten saplings, not caster");l.getDataStorage().set("kelmagic_grove_jobs",GroveAwakening.load(saved,l.registryAccess()));ok(true,"resume centre-first queue from persisted progress");}
   if(jobs.isEmpty()){smallDone=true;int old=0,midnight=0;for(var q:BlockPos.betweenClosed(GROVE.offset(-15,0,-15),GROVE.offset(15,34,15))){var state=l.getBlockState(q);if(state.is(Blocks.OAK_LOG)||state.is(Blocks.OAK_LEAVES))old++;if(state.is(MagicGrove.LOG.get())||state.is(MagicGrove.WOOD_BLOCK.get()))midnight++;}ok(old==0,"all 33635 sampled positions free of old oak logs and leaves");ok(midnight>0,"grove creation grows at least one midnight tree");ok(l.getBlockState(GROVE.offset(0,0,-3)).is(Blocks.DANDELION),"flower preserved");ok(l.getBiome(GROVE).is(GroveAwakening.BIOME),"server biome at sapling centre");ok(MagicProgress.completed(p,"rite_grove_awakening"),"grove completion awarded");p.getInventory().setItem(5,MagicDreams.GRASS_ITEM.toStack());MagicProgress.inventory(p);ok(MagicProgress.completed(p,"magic_turf"),"soil advancement after grove");benchStart=System.nanoTime();l.getDataStorage().set("kelmagic_grove_jobs",GroveAwakening.load(jobTag(p,BENCH,150,true),l.registryAccess()));System.out.println("R12_BENCH_START radius=150 player_distance="+p.position().distanceTo(Vec3.atCenterOf(BENCH)));}
  }else if(!benchDone&&jobs.isEmpty()){benchDone=true;System.out.println("R12_BENCH_COMPLETE seconds="+((System.nanoTime()-benchStart)/1e9));ok(l.getBlockState(BENCH.below()).is(MagicDreams.GRASS.get()),"full radius150 work proceeds away from player");ok(l.getBiome(BENCH).is(GroveAwakening.BIOME),"full radius150 changes biome");}
 }
 static CodexScreen book(){ResearchClient.state=ResearchState.EMPTY.add("tabs","great");return new CodexScreen(new dev.kelmagic.network.CodexOpen(List.of(),List.of(),false,6,0,"","r12",0,true,false));}
 @net.neoforged.bus.api.SubscribeEvent public static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("kelmagic.r12QA"))return;var m=Minecraft.getInstance();if(failure!=null)throw new RuntimeException(failure);if(m.getOverlay()!=null)return;if(m.level==null){if(!opened&&m.screen instanceof TitleScreen&&++wait>30){opened=true;m.createWorldOpenFlows().openWorld("KelMagicR12QA",()->{});}return;}if(m.player==null||m.getSingleplayerServer()==null)return;if(!requested){requested=true;server(QaR12Roots::tests);return;}if(!ready)return;
  if(!configured){configured=true;m.options.enableVsync().set(false);m.options.framerateLimit().set(40);m.options.renderDistance().set(12);m.options.guiScale().set(2);m.options.languageCode="ru_ru";m.resizeDisplay();m.getToasts().clear();try{Files.createDirectories(OUT);}catch(Exception ex){throw new RuntimeException(ex);}var b=book();for(var id:List.of("threshold_link","grove_awakening")){var n=ResearchCatalog.BY_ID.get("rite:"+id);ok(b.graphNodes().contains(n)&&b.entryLearned(n),"normal codex can read documented rite "+id);ok(!ResearchCatalog.learned(ResearchClient.state,n.id()),"book did not unlock survival research "+id);}ok(new MagicGrassRenderer(null).getViewDistance()<=128,"batched turf overlay stays inside the optimized 128-block radius");}
  if(frame%10==0)server(QaR12Roots::watch);int s=frame/120,t=frame%120;if(s>=12){if(benchDone){System.out.println("R12_NATIVE_COMPLETE checks="+checks);m.stop();}else if(frame>12000)throw new AssertionError("R12 benchmark timeout");frame++;return;}
  if(stage!=s){stage=s;m.options.hideGui=true;m.setScreen(null);if(s==0)server(p->camera(p,new Vec3(202,-58,3),new Vec3(200.5,-59.3,0)));if(s==1)server(p->camera(p,new Vec3(201.7,-58,-3.4),new Vec3(200.5,-59.3,-.5)));if(s==2)server(p->camera(p,new Vec3(158,-41,25),new Vec3(180,-49,0)));if(s==3||s==4)server(p->camera(p,new Vec3(228,-25,83),new Vec3(228,-60,47)));if(s==5)server(p->camera(p,new Vec3(200,-57,5),new Vec3(210,-59,12)));if(s==6){var b=book();m.setScreen(b);}if(s==7||s==8){var b=book();var n=ResearchCatalog.BY_ID.get(s==7?"rite:threshold_link":"rite:grove_awakening");var entry=new ResearchEntryScreen(b,n);m.setScreen(entry);try{var f=ResearchEntryScreen.class.getDeclaredField("pages");f.setAccessible(true);var pages=(List<?>)f.get(entry);f=ResearchEntryScreen.class.getDeclaredField("spread");f.setAccessible(true);f.setInt(entry,pages.size()/2);ok(true,"opened formula pages "+n.id());}catch(Exception ex){throw new RuntimeException(ex);}}if(s==10)server(p->camera(p,new Vec3(228,90,47),new Vec3(228,-60,47)));if(s==11)server(p->camera(p,new Vec3(200.5,-59,3),new Vec3(200.5,-59.5,0)));if(s==9)server(p->camera(p,new Vec3(325,-45,25),new Vec3(325,-57,0)));}
  if(t==90){Screenshot.grab(OUT.toFile(),"r12-"+s+".png",m.getMainRenderTarget(),c->{});System.out.println("R12_CAPTURE "+s);}frame++;
 }
}
